package ru.projectkingdom.npc;import java.util.*;import net.minecraft.server.*;public class KingdomCivicsData {public record Town(UUID id,String name,UUID mayor,UUID nation,long treasury){}public static final Map<MinecraftServer,KingdomCivicsData> INST=new HashMap<>();public static KingdomCivicsData get(MinecraftServer s){return INST.computeIfAbsent(s,k->new KingdomCivicsData());}public final Map<UUID,Town> towns=new HashMap<>();public final Map<UUID,UUID> members=new HashMap<>();public Town townOf(UUID person){return towns.get(members.get(person));}public Town townById(UUID id){return towns.get(id);}public boolean payTownObligation(UUID townId,long amount){Town t=towns.get(townId);if(t==null||t.treasury<amount)return false;towns.put(t.id,new Town(t.id,t.name,t.mayor,t.nation,t.treasury-amount));return true;}public boolean refundTown(UUID townId,long amount){Town t=towns.get(townId);towns.put(t.id,new Town(t.id,t.name,t.mayor,t.nation,t.treasury+amount));return true;}public boolean depositVerifiedTax(UUID townId,long amount){Town t=towns.get(townId);if(t==null||t.treasury>Long.MAX_VALUE-amount)return false;towns.put(t.id,new Town(t.id,t.name,t.mayor,t.nation,t.treasury+amount));return true;}}